DECLARE
  v_uid     text := auth.uid();
  v_hidden  boolean := coalesce(p_hidden, true);
  v_ts      timestamptz := CASE WHEN coalesce(p_hidden, true) THEN now() ELSE NULL END;
  v_thread  public.chat_threads%ROWTYPE;
  v_is_user boolean;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_thread_id IS NULL THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_thread FROM public.chat_threads WHERE id = p_thread_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_is_user := (v_thread.user_uid = v_uid);
  IF NOT v_is_user AND v_thread.peer_uid <> v_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.chat_threads
     SET user_hidden_at = CASE WHEN v_is_user THEN v_ts ELSE user_hidden_at END,
         peer_hidden_at = CASE WHEN v_is_user THEN peer_hidden_at ELSE v_ts END
   WHERE id = p_thread_id
  RETURNING * INTO v_thread;

  RETURN jsonb_build_object(
    '[literal]', v_hidden,
    '[literal]', CASE WHEN v_is_user THEN v_thread.user_hidden_at ELSE v_thread.peer_hidden_at END,
    '[literal]', to_jsonb(v_thread)
  );
END;

DECLARE
  v_uid       text := auth.uid();
  v_type      text := btrim(coalesce(p_topic_type, '[literal]'));
  v_peer      text := btrim(coalesce(p_peer_uid, '[literal]'));
  v_title     text := btrim(coalesce(p_topic_title, '[literal]'));
  v_peer_name text := btrim(coalesce(p_peer_name, '[literal]'));
  v_peer_role text := coalesce(nullif(btrim(p_peer_role), '[literal]'), '[literal]');
  v_my_name   text;
  v_row       public.chat_threads%ROWTYPE;
  v_inserted  integer := 0;
  v_restored  boolean := false;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_type = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_peer = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_peer = v_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_my_name
    FROM public.profiles p WHERE p.uid = v_uid;
  v_my_name := coalesce(v_my_name, '[literal]');

  IF v_peer_name = '[literal]' THEN
    SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_peer_name
      FROM public.profiles p WHERE p.uid = v_peer;
    v_peer_name := coalesce(v_peer_name, '[literal]');
  END IF;

  -- 幂等一：同话题 + 同参与者（不分方向）已存在 → 直接复用，并清掉我这一侧的隐藏
  SELECT * INTO v_row
    FROM public.chat_threads t
   WHERE t.topic_type = v_type
     AND coalesce(t.topic_id, 0) = coalesce(p_topic_id, 0)
     AND ((t.user_uid = v_uid AND t.peer_uid = v_peer)
       OR (t.user_uid = v_peer AND t.peer_uid = v_uid));
  IF FOUND THEN
    v_restored := (v_row.user_uid = v_uid AND v_row.user_hidden_at IS NOT NULL)
               OR (v_row.peer_uid = v_uid AND v_row.peer_hidden_at IS NOT NULL);
    IF v_restored THEN
      UPDATE public.chat_threads
         SET user_hidden_at = CASE WHEN user_uid = v_uid THEN NULL ELSE user_hidden_at END,
             peer_hidden_at = CASE WHEN peer_uid = v_uid THEN NULL ELSE peer_hidden_at END
       WHERE id = v_row.id
      RETURNING * INTO v_row;
    END IF;
    RETURN jsonb_build_object('[literal]', false, '[literal]', v_restored, '[literal]', to_jsonb(v_row));
  END IF;

  -- 幂等二：并发下同方向同时开会话，唯一索引兜底（冲突时 ROW_COUNT = 0）
  INSERT INTO public.chat_threads (
    topic_type, topic_id, topic_title, user_uid, user_name, peer_uid, peer_name, peer_role
  ) VALUES (
    v_type, p_topic_id, v_title, v_uid, v_my_name, v_peer, v_peer_name, v_peer_role
  )
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  SELECT * INTO v_row
    FROM public.chat_threads t
   WHERE t.topic_type = v_type
     AND coalesce(t.topic_id, 0) = coalesce(p_topic_id, 0)
     AND ((t.user_uid = v_uid AND t.peer_uid = v_peer)
       OR (t.user_uid = v_peer AND t.peer_uid = v_uid));
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  RETURN jsonb_build_object('[literal]', v_inserted > 0, '[literal]', false, '[literal]', to_jsonb(v_row));
END;

DECLARE
  v_ref     bigint := coalesce(p_ref_id, 0);
  v_enabled boolean := coalesce(p_enabled, true);
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_scope IS NULL OR p_scope NOT IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_commission_bp IS NULL OR p_commission_bp < 0 OR p_commission_bp > 5000 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_rider_bp IS NULL OR p_rider_bp < 0 OR p_rider_bp > 5000 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_scope = '[literal]' AND v_ref <> 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF NOT v_enabled AND p_scope = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_scope = '[literal]' AND NOT EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.id = v_ref) THEN
    RAISE EXCEPTION '[literal]', v_ref;
  END IF;

  INSERT INTO public.commission_rules (scope, ref_id, commission_bp, rider_bp, enabled, updated_at)
  VALUES (p_scope, v_ref, p_commission_bp, p_rider_bp, v_enabled, now())
  ON CONFLICT (scope, ref_id) DO UPDATE
    SET commission_bp = EXCLUDED.commission_bp,
        rider_bp = EXCLUDED.rider_bp,
        enabled = EXCLUDED.enabled,
        updated_at = now();

  RETURN jsonb_build_object(
    '[literal]', p_scope,
    '[literal]', v_ref,
    '[literal]', p_commission_bp,
    '[literal]', p_rider_bp,
    '[literal]', v_enabled
  );
END;

DECLARE v_bypass boolean;
BEGIN
  -- 治理 RPC 内部 set_config(...,true) 仅在当前事务生效
  v_bypass := COALESCE(current_setting('[literal]', true), '[literal]') = '[literal]';
  IF NOT v_bypass THEN
    IF TG_OP = '[literal]' THEN
      -- 正常开户只允许全默认：新用户注册 / 匿名转正时带默认 false + null 属合法
