         OR NEW.banned_at IS NOT NULL
         OR NULLIF(NEW.banned_note, '[literal]') IS NOT NULL THEN
        RAISE EXCEPTION '[literal]';
      END IF;
    ELSIF TG_OP = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;

