DECLARE v_revoked boolean;
BEGIN
  SELECT s.operation_revoked INTO v_revoked FROM public.shop_stores s WHERE s.id = NEW.store_id FOR SHARE;
  IF coalesce(v_revoked, false) AND (TG_OP = '[literal]' OR NEW.status IN ('[literal]', '[literal]')) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

DECLARE v_owner text; v_revoked boolean; v_any_revoked boolean; v_other_active boolean;
BEGIN
  v_owner := CASE WHEN TG_OP = '[literal]' THEN OLD.owner_uid ELSE NEW.owner_uid END;
  IF TG_OP = '[literal]' AND OLD.owner_uid IS DISTINCT FROM NEW.owner_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  -- SHARE锁与撤权的store行锁协调，避免使用撤权前的经营资格继续写入。
  PERFORM s.id FROM public.shop_stores s WHERE s.owner_uid = v_owner ORDER BY s.id FOR SHARE;
  SELECT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = v_owner AND s.operation_revoked),
         EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = v_owner AND NOT s.operation_revoked AND s.status <> '[literal]')
    INTO v_any_revoked, v_other_active;
  v_revoked := v_any_revoked AND NOT v_other_active;
  IF v_revoked THEN
    IF TG_OP = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF NOT coalesce(public.is_admin_user(), false) THEN RAISE EXCEPTION '[literal]'; END IF;
    IF TG_TABLE_NAME = '[literal]' THEN
      IF NEW.status = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    END IF;
  END IF;
  IF TG_OP = '[literal]' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

DECLARE v_id bigint; v_revoked boolean; v_old_revoked boolean := false; v_refund_qty numeric; v_refund_order bigint;
BEGIN
  v_id := CASE WHEN TG_OP = '[literal]' THEN OLD.store_id ELSE NEW.store_id END;
  IF TG_TABLE_NAME = '[literal]' THEN
    SELECT s.operation_revoked INTO v_revoked FROM public.shop_stores s WHERE s.id = v_id FOR SHARE;
    IF TG_OP = '[literal]' AND OLD.store_id IS DISTINCT FROM NEW.store_id THEN
      SELECT s.operation_revoked INTO v_old_revoked FROM public.shop_stores s WHERE s.id = OLD.store_id FOR SHARE;
    END IF;
  ELSE
    SELECT s.operation_revoked INTO v_revoked FROM public.canteen_stores s WHERE s.id = v_id FOR SHARE;
    IF TG_OP = '[literal]' AND OLD.store_id IS DISTINCT FROM NEW.store_id THEN
      SELECT s.operation_revoked INTO v_old_revoked FROM public.canteen_stores s WHERE s.id = OLD.store_id FOR SHARE;
    END IF;
  END IF;
  IF coalesce(v_revoked, false) OR coalesce(v_old_revoked, false) THEN
    IF TG_OP = '[literal]' OR TG_OP = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF NEW.status <> '[literal]' OR OLD.store_id IS DISTINCT FROM NEW.store_id THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF NOT coalesce(public.is_admin_user(), false) THEN
      IF TG_TABLE_NAME <> '[literal]' OR
         (to_jsonb(NEW) - ARRAY['[literal]', '[literal]', '[literal]']) IS DISTINCT FROM
         (to_jsonb(OLD) - ARRAY['[literal]', '[literal]', '[literal]']) THEN
        RAISE EXCEPTION '[literal]';
      END IF;
      SELECT a.qty, a.order_id INTO v_refund_qty, v_refund_order FROM public.operation_stock_refund_authorization a
        WHERE a.txid = txid_current() AND a.goods_id = NEW.id AND a.actor_uid = auth.uid() AND NOT a.used
        ORDER BY a.order_id LIMIT 1 FOR UPDATE;
      IF v_refund_qty IS NULL OR NEW.stock <> OLD.stock + v_refund_qty OR NEW.sold_out <> false THEN
        RAISE EXCEPTION '[literal]';
      END IF;
      UPDATE public.operation_stock_refund_authorization SET used = true
        WHERE txid = txid_current() AND order_id = v_refund_order AND goods_id = NEW.id;
    END IF;
  END IF;
  IF TG_OP = '[literal]' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.status = '[literal]' AND NEW.role = '[literal]' AND
     EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = NEW.uid AND s.operation_revoked) AND
     NOT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = NEW.uid AND NOT s.operation_revoked AND s.status <> '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NEW.status = '[literal]' AND NEW.role = '[literal]' AND
     EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.owner_uid = NEW.uid AND s.operation_revoked) AND
     NOT EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.owner_uid = NEW.uid AND NOT s.operation_revoked) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

DECLARE v_id bigint; v_revoked boolean; v_old_revoked boolean := false; v_owner text;
BEGIN
  v_id := CASE WHEN TG_OP = '[literal]' THEN OLD.store_id ELSE NEW.store_id END;
  IF TG_TABLE_NAME = '[literal]' THEN
    SELECT s.operation_revoked, s.owner_uid INTO v_revoked, v_owner FROM public.shop_stores s WHERE s.id = v_id FOR SHARE;
  ELSE
    SELECT s.operation_revoked, s.owner_uid INTO v_revoked, v_owner FROM public.canteen_stores s WHERE s.id = v_id FOR SHARE;
  END IF;
  IF TG_OP = '[literal]' AND OLD.store_id IS DISTINCT FROM NEW.store_id THEN
    IF TG_TABLE_NAME = '[literal]' THEN
      SELECT s.operation_revoked INTO v_old_revoked FROM public.shop_stores s WHERE s.id = OLD.store_id FOR SHARE;
    ELSE
      SELECT s.operation_revoked INTO v_old_revoked FROM public.canteen_stores s WHERE s.id = OLD.store_id FOR SHARE;
    END IF;
  END IF;
  IF coalesce(v_revoked, false) OR coalesce(v_old_revoked, false) THEN
    IF TG_OP = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF TG_OP = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF NEW.store_id IS DISTINCT FROM OLD.store_id THEN RAISE EXCEPTION '[literal]'; END IF;
    -- 店主可同时是骑手：只保留已审核骑手的配送字段路径，旧delivery_guard继续校验状态机。
    IF TG_TABLE_NAME = '[literal]' THEN
    IF coalesce(public.rider_is_approved(), false) AND (
       (OLD.rider_uid = '[literal]' AND OLD.delivery_status = '[literal]' AND NEW.rider_uid = auth.uid() AND NEW.delivery_status = '[literal]') OR
       (OLD.rider_uid = auth.uid() AND NEW.rider_uid = auth.uid()) OR
       (OLD.rider_uid = auth.uid() AND NEW.rider_uid = '[literal]' AND NEW.delivery_status = '[literal]')
       ) AND NEW.status = OLD.status AND
       (to_jsonb(NEW) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) =
       (to_jsonb(OLD) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) THEN
      RETURN NEW;
    END IF;
    -- 仅真实AFTER订单终态触发器里的结算更新；不能由旧店主直写结算列冒充履约。
    IF pg_trigger_depth() > 1 AND OLD.settle_status = '[literal]' AND NEW.settle_status = '[literal]' AND
       ((OLD.mode = '[literal]' AND OLD.status = '[literal]') OR (OLD.mode = '[literal]' AND OLD.delivery_status = '[literal]')) AND
       (to_jsonb(NEW) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) =
       (to_jsonb(OLD) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) THEN
      RETURN NEW;
    END IF;
    END IF;
    -- 买家RLS只保证账号归属；这里冻结订单快照、金额、身份及终态，防止改items后重复取消补库存。
    IF OLD.buyer_uid = auth.uid() AND NOT coalesce(public.is_admin_user(), false) THEN
      IF NEW.status = OLD.status AND
         (to_jsonb(NEW) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) =
         (to_jsonb(OLD) - ARRAY['[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]']) THEN
        RETURN NEW; -- 支付字段仍由既有order_pay_guard限定服务端写入。
      END IF;
      IF TG_TABLE_NAME = '[literal]' AND OLD.status = '[literal]' AND NEW.status = '[literal]' AND
         (to_jsonb(NEW) - ARRAY['[literal]', '[literal]']) = (to_jsonb(OLD) - ARRAY['[literal]', '[literal]']) THEN
        RETURN NEW;
      END IF;
      IF TG_TABLE_NAME = '[literal]' AND (
         (OLD.status IN ('[literal]', '[literal]') AND NEW.status = '[literal]') OR
         (OLD.mode = '[literal]' AND OLD.status = '[literal]' AND NEW.status = '[literal]')) AND
         (to_jsonb(NEW) - ARRAY['[literal]', '[literal]', '[literal]']) = (to_jsonb(OLD) - ARRAY['[literal]', '[literal]', '[literal]']) THEN
        IF NEW.delivery_status = OLD.delivery_status OR
           (OLD.mode = '[literal]' AND NEW.status = '[literal]' AND NEW.delivery_status = '[literal]') THEN
          RETURN NEW;
        END IF;
      END IF;
      RAISE EXCEPTION '[literal]';
    END IF;
    IF auth.uid() = v_owner AND NOT coalesce(public.is_admin_user(), false) THEN
      RAISE EXCEPTION '[literal]';
    END IF;
  END IF;
  IF TG_OP = '[literal]' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

DECLARE
  v_admin boolean := coalesce(public.is_admin_user(), false);
  v_governance boolean := v_admin AND coalesce(current_setting('[literal]', true), '[literal]') = '[literal]';
  v_revoked boolean;
BEGIN
  -- 建店与撤权同一事务锁串行；锁后重新查询，防止旧店主并发建新店绕过撤权。
  IF TG_OP = '[literal]' THEN PERFORM pg_advisory_xact_lock(612004, 1); END IF;
  IF TG_OP = '[literal]' THEN
    IF OLD.operation_revoked OR OLD.operation_cleared THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = '[literal]' THEN
    IF NEW.operation_revoked OR NEW.operation_cleared OR NEW.operation_reason <> '[literal]'
       OR NEW.operation_revoked_by <> '[literal]' OR NEW.operation_revoked_at IS NOT NULL THEN
      IF NOT v_governance THEN RAISE EXCEPTION '[literal]'; END IF;
    END IF;
    IF NOT v_admin THEN
      IF TG_TABLE_NAME = '[literal]' THEN
        SELECT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = NEW.owner_uid AND s.operation_revoked) INTO v_revoked;
      ELSE
        SELECT EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.owner_uid = NEW.owner_uid AND s.operation_revoked) INTO v_revoked;
      END IF;
      IF v_revoked THEN RAISE EXCEPTION '[literal]'; END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.operation_revoked, NEW.operation_cleared, NEW.operation_reason, NEW.operation_revoked_by, NEW.operation_revoked_at)
       IS DISTINCT FROM (OLD.operation_revoked, OLD.operation_cleared, OLD.operation_reason, OLD.operation_revoked_by, OLD.operation_revoked_at)
     AND NOT v_governance THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF OLD.operation_revoked AND NOT v_admin THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NEW.operation_revoked THEN
    IF NOT NEW.force_closed OR (TG_TABLE_NAME = '[literal]' AND NEW.status <> '[literal]')
       OR (TG_TABLE_NAME = '[literal]' AND NEW.status <> '[literal]') THEN
      RAISE EXCEPTION '[literal]';
    END IF;
  END IF;
  IF NEW.owner_uid IS DISTINCT FROM OLD.owner_uid AND NOT v_admin THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

DECLARE
  v_uid text := auth.uid();
  v_role text := lower(btrim(COALESCE(p_role, '[literal]')));
  v_payload jsonb := COALESCE(p_payload, '[literal]'::jsonb);
  v_member text;
  v_rejected_id bigint;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_role NOT IN ('[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF jsonb_typeof(v_payload) <> '[literal]' OR v_payload = '[literal]'::jsonb THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT m.status INTO v_member
    FROM public.role_members m
   WHERE m.uid = v_uid AND m.role = v_role;
  IF v_member = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_member = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF EXISTS (SELECT 1 FROM public.role_apps
              WHERE uid = v_uid AND role = v_role AND status = '[literal]') THEN
    -- 待审中重复提交：覆盖资料，保持单条待审
    UPDATE public.role_apps
       SET payload = v_payload, reply = '[literal]', handled_at = NULL, updated_at = now()
     WHERE uid = v_uid AND role = v_role AND status = '[literal]';
  ELSE
    SELECT a.id INTO v_rejected_id
      FROM public.role_apps a
     WHERE a.uid = v_uid AND a.role = v_role AND a.status = '[literal]'
     ORDER BY a.created_at DESC
     LIMIT 1;
    IF v_rejected_id IS NOT NULL THEN
      -- 驳回后重新提交：复用原单据转回待审
      UPDATE public.role_apps
         SET payload = v_payload, status = '[literal]', reply = '[literal]', handled_at = NULL, updated_at = now()
       WHERE id = v_rejected_id;
    ELSE
      INSERT INTO public.role_apps (uid, role, payload, status)
      VALUES (v_uid, v_role, v_payload, '[literal]');
    END IF;
  END IF;
  RETURN '[literal]';
END;

SELECT EXISTS (
  SELECT 1 FROM public.role_members m
  WHERE m.uid = auth.uid()
    AND m.role = lower(btrim(COALESCE(p_role, '[literal]')))
    AND m.status = '[literal]'
);

DECLARE
  v_role text := lower(btrim(COALESCE(p_role, '[literal]')));
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_role NOT IN ('[literal]', '[literal]', '[literal]') THEN
