DECLARE
  v_applicant text;
  v_role text;
  v_payload jsonb;
  v_reason text := btrim(COALESCE(p_reason, '[literal]'));
  v_name text := '[literal]';
  v_emoji text := '[literal]';
  v_building text := '[literal]';
  v_desc text := '[literal]';
  v_phone text := '[literal]';
  v_category text := '[literal]';
  v_tags text[] := '[literal]';
  v_display text := '[literal]';
  v_store_id bigint;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT a.uid, a.role, a.payload INTO v_applicant, v_role, v_payload
    FROM public.role_apps a
   WHERE a.id = p_app_id AND a.status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 驳回：填写原因即可，业务侧不落地
  IF NOT p_ok THEN
    IF v_reason = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    UPDATE public.role_apps
       SET status = '[literal]', reply = v_reason, handled_at = now(), updated_at = now()
     WHERE id = p_app_id AND status = '[literal]';
    IF NOT FOUND THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RETURN true;
  END IF;

  -- 通过：原子占位申请单（并发下只有一个管理员能抢到）
  UPDATE public.role_apps
     SET status = '[literal]', reply = '[literal]', handled_at = now(), updated_at = now()
   WHERE id = p_app_id AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_role = '[literal]' THEN
    -- 档口：按既有 canteen_stores 列默认与 CHECK 建档（或复用已存在档口），并回填 ref_id
    v_name := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
    v_emoji := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
    v_building := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_desc := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_tags := COALESCE(
      (SELECT array_agg(t) FROM jsonb_array_elements_text(COALESCE(v_payload -> '[literal]', '[literal]'::jsonb)) AS x(t)),
      '[literal]'
    );
    v_display := v_name;

    SELECT s.id INTO v_store_id
      FROM public.canteen_stores s
     WHERE s.owner_uid = v_applicant
     ORDER BY s.created_at
     LIMIT 1;

    IF v_store_id IS NULL THEN
      INSERT INTO public.canteen_stores (owner_uid, name, emoji, description, tags, building, status)
      VALUES (v_applicant, v_name, v_emoji, v_desc, v_tags, v_building, '[literal]')
      RETURNING id INTO v_store_id;
    ELSE
      UPDATE public.canteen_stores
         SET name = v_name, emoji = v_emoji, description = v_desc, tags = v_tags,
             building = v_building, status = '[literal]', updated_at = now()
       WHERE id = v_store_id;
    END IF;

  ELSIF v_role = '[literal]' THEN
    -- 骑手：开通既有的 rider_profiles 身份（该表同时承载骑手在线开关与配送归属）
    v_name := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_phone := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_building := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_desc := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    IF v_name = '[literal]' OR v_phone = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    v_display := v_name;

    INSERT INTO public.rider_profiles (uid, real_name, phone, zone, note, status, reply, handled_at, online)
    VALUES (v_applicant, v_name, v_phone, v_building, v_desc, '[literal]', '[literal]', now(), false)
    ON CONFLICT (uid) DO UPDATE
       SET real_name = EXCLUDED.real_name,
           phone = EXCLUDED.phone,
           zone = EXCLUDED.zone,
           note = EXCLUDED.note,
           status = '[literal]',
           reply = '[literal]',
           handled_at = now(),
           updated_at = now();

  ELSE
    -- 小店：仅开通成员身份，商品与流水由工作台自行维护
    v_category := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_display := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
  END IF;

  -- 成员开通（幂等：重复审批/停用恢复共用同一路径）
  INSERT INTO public.role_members (uid, role, status, display_name, ref_id, joined_at)
  VALUES (v_applicant, v_role, '[literal]', v_display, v_store_id, now())
  ON CONFLICT (uid, role) DO UPDATE
     SET status = '[literal]',
         display_name = EXCLUDED.display_name,
         ref_id = COALESCE(EXCLUDED.ref_id, public.role_members.ref_id),
         updated_at = now();

  RETURN true;
END;

DECLARE
  v_role text := lower(btrim(COALESCE(p_role, '[literal]')));
  v_store record;
  v_has_store boolean := false;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_role NOT IN ('[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_role IN ('[literal]', '[literal]') THEN
    -- 停用owner整个经营角色的旧接口必须在枚举前取得与建店相同的锁。
    PERFORM pg_advisory_xact_lock(612004, 1);
    FOR v_store IN
      SELECT s.id FROM public.shop_stores s WHERE v_role = '[literal]' AND s.owner_uid = p_uid
      UNION ALL
      SELECT s.id FROM public.canteen_stores s WHERE v_role = '[literal]' AND s.owner_uid = p_uid
      ORDER BY id
    LOOP
      v_has_store := true;
      PERFORM public.admin_operation_revoke(v_role, v_store.id, '[literal]', false);
    END LOOP;
    IF v_has_store THEN RETURN true; END IF;
  END IF;

  UPDATE public.role_members
     SET status = '[literal]', updated_at = now()
   WHERE uid = p_uid AND role = v_role AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 业务侧同步：骑手立刻下线且不可再推进配送；档口转为歇业（公开视图随之下架）
  IF v_role = '[literal]' THEN
    UPDATE public.rider_profiles
       SET status = '[literal]', online = false, handled_at = now(), updated_at = now()
     WHERE uid = p_uid;
  ELSIF v_role = '[literal]' THEN
    UPDATE public.canteen_stores
       SET status = '[literal]', updated_at = now()
     WHERE owner_uid = p_uid;
  END IF;

  RETURN true;
END;

DECLARE
  v_store public.canteen_stores%ROWTYPE;
  v_closed boolean := coalesce(p_closed, false);
  v_note text := coalesce(btrim(p_note), '[literal]');
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_store FROM public.canteen_stores WHERE id = p_store_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]', p_store_id;
  END IF;

  UPDATE public.canteen_stores
     SET force_closed = v_closed,
         force_close_note = CASE WHEN v_closed THEN v_note ELSE '[literal]' END,
         force_closed_at = CASE WHEN v_closed THEN now() ELSE NULL END
   WHERE id = p_store_id;

  PERFORM public.notify_push(
    v_store.owner_uid, '[literal]',
    CASE WHEN v_closed THEN '[literal]' ELSE '[literal]' END,
    CASE WHEN v_closed
         THEN format('[literal]', v_store.name,
                     CASE WHEN v_note = '[literal]' THEN '[literal]' ELSE '[literal]' || v_note END)
         ELSE format('[literal]', v_store.name) END,
    '[literal]', p_store_id
  );

  RETURN jsonb_build_object('[literal]', p_store_id, '[literal]', v_closed);
END;

DECLARE
  v_uid text := auth.uid();
  v_bal bigint;
  v_id  bigint;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_account IS NULL OR p_account NOT IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_amount_cent IS NULL OR p_amount_cent <= 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(coalesce(p_real_name, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(coalesce(p_alipay, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.wallets
     SET balance_cent = balance_cent - p_amount_cent,
         frozen_cent = frozen_cent + p_amount_cent,
         updated_at = now()
   WHERE uid = v_uid AND account = p_account AND balance_cent >= p_amount_cent
  RETURNING balance_cent INTO v_bal;

  IF NOT FOUND THEN
    SELECT w.balance_cent INTO v_bal
      FROM public.wallets w
     WHERE w.uid = v_uid AND w.account = p_account;
    IF v_bal IS NULL THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RAISE EXCEPTION '[literal]', to_char(v_bal / 100.0, '[literal]');
  END IF;

  INSERT INTO public.withdraw_apps (uid, account, amount_cent, real_name, alipay)
  VALUES (v_uid, p_account, p_amount_cent, btrim(p_real_name), btrim(p_alipay))
  RETURNING id INTO v_id;

  INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, memo)
  VALUES (v_uid, p_account, '[literal]', -p_amount_cent, v_bal, '[literal]');

  PERFORM public.notify_push(
    v_uid, '[literal]', '[literal]',
    format('[literal]', to_char(p_amount_cent / 100.0, '[literal]')),
    '[literal]', v_id
  );

  RETURN jsonb_build_object('[literal]', v_id, '[literal]', p_amount_cent, '[literal]', v_bal);
END;

DECLARE
  v_app public.withdraw_apps%ROWTYPE;
  v_bal bigint;
  v_reason text;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_app FROM public.withdraw_apps WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]', p_id;
  END IF;
  IF v_app.status <> '[literal]' THEN
    RAISE EXCEPTION '[literal]', v_app.status;
  END IF;

  v_reason := coalesce(btrim(p_reason), '[literal]');

  IF p_ok THEN
    UPDATE public.wallets
       SET frozen_cent = greatest(frozen_cent - v_app.amount_cent, 0),
           updated_at = now()
     WHERE uid = v_app.uid AND account = v_app.account;

    UPDATE public.withdraw_apps
       SET status = '[literal]', reply = v_reason, handled_by = auth.uid(), handled_at = now()
     WHERE id = p_id;

    PERFORM public.notify_push(
      v_app.uid, '[literal]', '[literal]',
      format('[literal]', to_char(v_app.amount_cent / 100.0, '[literal]')),
      '[literal]', p_id
    );
  ELSE
    IF v_reason = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;

    UPDATE public.wallets
       SET balance_cent = balance_cent + v_app.amount_cent,
           frozen_cent = greatest(frozen_cent - v_app.amount_cent, 0),
           updated_at = now()
     WHERE uid = v_app.uid AND account = v_app.account
    RETURNING balance_cent INTO v_bal;

    INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, memo)
    VALUES (v_app.uid, v_app.account, '[literal]', v_app.amount_cent, coalesce(v_bal, 0),
            format('[literal]', v_reason));

    UPDATE public.withdraw_apps
       SET status = '[literal]', reply = v_reason, handled_by = auth.uid(), handled_at = now()
     WHERE id = p_id;

    PERFORM public.notify_push(
      v_app.uid, '[literal]', '[literal]',
      format('[literal]', to_char(v_app.amount_cent / 100.0, '[literal]'), v_reason),
      '[literal]', p_id
    );
  END IF;

  RETURN jsonb_build_object(
    '[literal]', p_id,
    '[literal]', CASE WHEN p_ok THEN '[literal]' ELSE '[literal]' END
  );
END;
